from concurrent.futures import ThreadPoolExecutor
from PIL import Image,ImageOps
from produce import EP,request,save
import hashlib
OUT=EP/'image/character-options/v2';OUT.mkdir(parents=True,exist_ok=True)
BASE='''Create ONE full-body Chinese adult male professional cleaner, around 38-42, sturdy average build, short black hair, clean-shaven, composed observant expression. Entire body and shoes visible, natural relaxed three-quarter pose, arms relaxed, two yellow rubber cleaning gloves, faded slate-blue work jacket, charcoal work trousers, worn dark work shoes. Same garment colors and same approximate age in both design directions. Full-frame horizontal 16:9, one person only, no panels, lettering, logo or watermark. Attached room is BACKGROUND REFERENCE ONLY: preserve hand-painted sea-green kitchen tiles, old cabinet, window daylight, garbage at edges; match its softly textured painterly material and light. Place person on central floor, feet grounded with contact shadow, no foreground trash hiding body. The aim is an appealing slightly anime-influenced adult human that belongs naturally inside this textured painted room. NOT photorealistic, NOT realistic portrait illustration, NOT gritty graphic novel, NOT a caricature or stick figure. Natural skin color, readable eyes, nose and mouth, simplified adult face, no wrinkles, stubble, skin pores or sculpted facial anatomy. No giant glossy eyes, no sparkles, no spiky fantasy hair, no teenage idol appearance, no heroic pose, no chibi body, no exaggerated muscles. Clothes show just a few broad folds and slight work wear, not dense scratchy texture. Restrained muted color, soft-edged painted shadows and reflected room light; same rendering coherence between face, clothes, and environment. '''
OPTIONS=[('D','轻动漫手绘','Adult proportions around 7 heads tall. Subtle anime influence only: slightly softened face shape, medium-small almond eyes with simple eyelids and tiny highlights, understated small nose, short natural slightly tousled hair grouped into broad shapes. Broken fine brown-grey outlines, loose gouache brush texture, soft broad shadow shapes; character detail simplified by about one third compared with realistic adult illustration. Calm capable ordinary worker with a touch of warmth. Avoid sharp cheekbone lines and harsh facial shading.'),('E','动漫感稍强','Adult proportions around 6.5-7 heads tall, mature not youthful. Moderately anime-influenced face with slightly larger but restrained almond eyes, simplified brows and small nose, rounded clean cheek contours, short black hair in soft grouped locks. Expressive reserved attentive face. Clean thin muted brown outlines combined with painted edges, two or three gentle broad color shapes per garment, a little brush texture and soft room reflected light. The face is stylized but adult, body and clothing grounded and natural; do not render fully flat cel anime or polished digital game character.')]
def gen(pair):
 i,(key,name,desc)=pair;prompt=BASE+desc;bg=EP/'image/backgrounds/kitchen-full.png';src=request('worker-soft-anime-'+key.lower(),prompt,i,bg,dict(stage='episode-character-candidate',option=key,name=name,cast='worker',reference_roles={str(bg):'background style and environment light only'},user_direction='偏动漫一点点，但不要完全动漫'))
 out=OUT/f'清理垃圾屋_主角{key}_{name}.png'
 with Image.open(src) as im:ImageOps.fit(im.convert('RGB'),(1920,1080),method=Image.Resampling.LANCZOS).save(out)
 return dict(option=key,name=name,file=str(out.relative_to(EP)),sha256=hashlib.sha256(out.read_bytes()).hexdigest())
if __name__=='__main__':
 with ThreadPoolExecutor(max_workers=2) as pool:rows=list(pool.map(gen,enumerate(OPTIONS)))
 save(EP/'qa/character-options-current.json',dict(status='待目检',direction='适度动漫化，成人比例与手绘环境融合',options=rows));print('READY',flush=True)
